<style>
@font-face{font-family:Proof;src:url("data:font/otf;base64,") format("opentype");font-display:swap}
:root{--stock:#e57156;--paper:#fff8e8;--ink:#202a45;--muted:#575564;--rule:#b9ac96;--pass:#245a43;--error:#9b301f}
*{box-sizing:border-box}
