<body>
<main class="folio">
<nav aria-label="Page"><a href="index.php">Chloe Reads Jon</a><span>A little export-rescue game</span></nav>
<h1>Pixel Proof</h1>
<p class="intro">A lovely picture. A terrible export. Rescue three print-shop jobs by finding just enough detail, sensible compression, and a little breathing room.</p>
<section aria-labelledby="job-title">
<div class="job"><span id="job-count">Job 1 of 3</span><h2 id="job-title" tabindex="-1">The email attachment</h2></div>
<p id="brief">Keep the artwork clear at 150 PPI or better, use gentle compression, leave at least 8 mm at the top, and stay within a 220 KB model budget.</p>
<div class="work">
<figure>
<div class="plate-labels"><span>Original artwork</span><span>Your export</span></div>
<div class="plate" id="plate">
<canvas id="export" width="900" height="600" role="img" aria-label="Your export preview, with resolution, JPEG compression and top placement applied."></canvas>
<canvas id="original" width="900" height="600" role="img" aria-label="Original illustration of a red vintage station wagon outside a seaside print shop."></canvas><div class="seam" id="seam"></div>
<div id="loading">Preparing the proof…</div>
</div>
<label class="scrub" for="compare">Compare original and export <output id="compare-value">50% original</output></label>
<input id="compare" type="range" min="0" max="100" value="50">
<figcaption>Slide left to see the whole export. Try 72 PPI and watch the fine lines disappear. The top edge is deliberately unforgiving.</figcaption>
</figure>
<div class="controls">
<fieldset>
<legend>Prepare your export</legend>
<label class="control" for="resolution">Image resolution</label>
<select id="resolution"><option value="72">72 PPI · a rough preview</option><option value="150">150 PPI · small and useful</option><option value="300">300 PPI · print detail</option><option value="600">600 PPI · extra pixels</option></select>
<small>For this model, the picture prints 2 inches wide. More pixels cost more space.</small>
</fieldset>
<fieldset>
<label class="control" for="compression">Compression</label>
<select id="compression"><option value="strong">Strong JPEG · smaller, rougher</option><option value="light">Gentle JPEG · a compromise</option><option value="lossless">Lossless PNG · keep every pixel</option></select>
</fieldset>
<fieldset>
<div class="control-row"><label class="control" for="margin">Top clearance</label><output id="margin-value">2 mm</output></div>
<input id="margin" type="range" min="0" max="16" step="1" value="2">
<small>Below 8 mm, part of the picture crosses the simulated printable edge.</small>
</fieldset>
<div class="estimate"><span>Model file size</span><strong id="size">14 KB / 220 KB</strong></div>
<div class="actions"><button id="check" disabled>Check proof</button><button class="secondary" id="hint">Hint</button></div>
<p id="feedback" role="status" aria-live="polite">Loading the artwork. Your proof will be ready in a moment.</p>
<button id="next" hidden>Next job</button>
<div class="actions"><button class="secondary" id="download" disabled>Save this export</button><button class="secondary" id="restart">Start over</button></div>
<small id="save-note">Downloads a real raster image, not a PDF. Its actual byte size will differ from the model.</small>
</div>
</div>
</section>
<section class="notes" aria-label="What the experiment shows">
<div><h3>Why the numbers matter</h3><p>PPI is pixels per printed inch. Double it in both directions and you get four times as many pixels. Printer DPI measures ink dots and is a different thing. Adding pixels cannot recover detail missing from the original.</p></div>
<div><h3>A small echo of a real headache</h3><p>In 2004, Jon was chasing blurry screenshots, disappearing graphics and a 70 MB quick-reference PDF. These fictional jobs borrow those problems. The preview really resamples and JPEG-compresses the art; the budgets are teaching estimates, not PDF predictions.</p></div>
</section>
<footer>Inspired by Jon's <a href="?inspiration=1">Word-to-PDF notes</a>. Original artwork made for this experiment. Everything runs in your browser; no uploads.</footer>
<noscript><p>This game needs JavaScript for the image comparison and export controls.</p></noscript>
</main>
<script>
'use strict';
const $=id=>document.getElementById(id);
const art=new Image();
const jobs=[
{title:'The email attachment',brief:'Keep the artwork clear at 150 PPI or better, use gentle compression, leave at least 8 mm at the top, and stay within a 220 KB model budget.',min:150,cap:220,margin:8,kind:'light',hint:'Try 150 PPI, Gentle JPEG and 8 mm. The goal is useful detail, not maximum pixels.',lesson:'Approved. 150 PPI and gentle compression keep this small attachment clear without hauling a printing press into the inbox.'},
{title:'The keepsake print',brief:'Preserve fine linework at 300 PPI or better with lossless PNG, leave at least 8 mm at the top, and stay within a 2,000 KB model budget.',min:300,cap:2000,margin:8,kind:'lossless',hint:'Try 300 PPI, Lossless PNG and 8 mm. 600 PPI makes four times as many pixels as 300.',lesson:'Approved. Lossless PNG avoids JPEG damage around fine edges. 300 PPI meets this job without the extra weight of 600.'},
{title:'The gallery handout',brief:'Deliver 300 PPI or better, avoid strong JPEG, leave at least 12 mm for the handout header, and stay within an 800 KB model budget.',min:300,cap:800,margin:12,kind:'either',hint:'Try 300 PPI, Gentle JPEG and 12 mm. The header needs more room than the earlier jobs.',lesson:'All three proofs approved! You have earned a quiet afternoon at the print shop. Keep experimenting or save your favourite export.'}
];
let job=0,ready=false,approved=false,free=false,token=0,exportURL='',currentRendered=false;
function settings(){return {ppi:Number($('resolution').value),kind:$('compression').value,margin:Number($('margin').value)}}
function model(s){return Math.round((s.ppi/150)**2*({strong:60,light:160,lossless:450}[s.kind]))}
function say(text,good){$('feedback').textContent=text;$('feedback').className=good===undefined?'':good?'good':'bad'}
function compare(){const x=Number($('compare').value);$('original').style.clipPath='inset(0 '+(100-x)+'% 0 0)';$('seam').style.left=x+'%';$('compare-value').textContent=x+'% original'}
function place(ctx,image,margin){ctx.fillStyle='#fff8e8';ctx.fillRect(0,0,900,600);ctx.save();ctx.beginPath();ctx.rect(30,40,840,530);ctx.clip();const y=40+(margin-8)*6;ctx.drawImage(image,30,y,840,530);ctx.restore();ctx.strokeStyle='#202a45';ctx.lineWidth=1;ctx.strokeRect(30,40,840,530)}
async function render(){
const s=settings(),mine=++token;currentRendered=false;
$('size').textContent=model(s).toLocaleString('en-CA')+' KB'+(free?'':' / '+jobs[job].cap.toLocaleString('en-CA')+' KB');
$('margin-value').textContent=s.margin+' mm';$('download').disabled=true;$('check').disabled=true;
if(!ready)return;
const small=document.createElement('canvas');small.width=Math.round(s.ppi*2);small.height=Math.round(small.width*2/3);
small.getContext('2d').drawImage(art,0,0,small.width,small.height);
const url=small.toDataURL(s.kind==='lossless'?'image/png':'image/jpeg',s.kind==='strong'?.08:.7);
const compressed=new Image();compressed.src=url;
try{await compressed.decode()}catch(e){if(mine===token)say('The preview could not be rendered. Try another resolution.',false);return}
if(mine!==token)return;
place($('export').getContext('2d'),compressed,s.margin);
place($('original').getContext('2d'),art,8);
exportURL=url;currentRendered=true;$('download').disabled=false;$('check').disabled=false;
}
function changed(){
approved=false;$('next').hidden=true;$('check').textContent=free?'Check experiment':'Check proof';
say(free?'Free play. Change anything and compare the result.':'Settings changed. Inspect the export, then check your proof.');
render();
}
function check(){
if(!currentRendered)return;const s=settings(),j=jobs[job],issues=[];
if(s.ppi<j.min)issues.push('Increase resolution to at least '+j.min+' PPI.');
if(j.kind==='lossless'&&s.kind!=='lossless')issues.push('Choose Lossless PNG to protect the linework.');
else if(j.kind!=='lossless'&&s.kind==='strong')issues.push('Use Gentle JPEG or Lossless PNG; strong JPEG is too rough.');
if(s.margin<j.margin)issues.push('Give the top at least '+j.margin+' mm of clearance.');
if(model(s)>j.cap)issues.push('The model file is too large. Reduce resolution'+(j.kind==='lossless'?'.':' or use Gentle JPEG.'));
if(issues.length){say(issues.join(' '),false);return}
say(free?'This still meets the gallery handout brief. Try comparing the strongest and weakest settings.':j.lesson,true);
if(!free){approved=true;$('plate').classList.remove('approved');void $('plate').offsetWidth;$('plate').classList.add('approved');$('next').hidden=false;$('next').textContent=job===2?'Open free play':'Next job';}
}
function next(){
if(!approved)return;
if(job===2){free=true;$('job-count').textContent='Three jobs approved';$('job-title').textContent='The print shop is yours';$('brief').textContent='Free play: exaggerate the settings, compare the result, and save any version you like.';$('next').hidden=true;$('check').textContent='Check experiment';}
else{job++;loadJob()}
$('job-title').focus();render();
}
function loadJob(){const j=jobs[job];approved=false;free=false;$('job-count').textContent='Job '+(job+1)+' of 3';$('job-title').textContent=j.title;$('brief').textContent=j.brief;$('next').hidden=true;$('check').textContent='Check proof';say('Inspect the export and adjust the settings for this job.');}
['resolution','compression'].forEach(id=>$(id).addEventListener('change',changed));
$('margin').addEventListener('input',changed);$('compare').addEventListener('input',compare);
$('check').addEventListener('click',check);$('hint').addEventListener('click',()=>say(free?'Try 72 PPI with strong JPEG, then compare it with 600 PPI and PNG.':jobs[job].hint));
$('next').addEventListener('click',next);
$('restart').addEventListener('click',()=>{job=0;$('resolution').value='72';$('compression').value='strong';$('margin').value='2';$('compare').value='50';compare();loadJob();render();$('job-title').focus()});
$('download').addEventListener('click',()=>{if(!currentRendered)return;const a=document.createElement('a');a.href=exportURL;a.download='pixel-proof-'+settings().ppi+'ppi.'+(settings().kind==='lossless'?'png':'jpg');a.click();$('save-note').textContent='Saved the resampled artwork. Top clearance belongs to the proof layout and is not baked into this image.'});
art.onload=()=>{ready=true;$('loading').hidden=true;loadJob();render()};
art.onerror=()=>{$('loading').textContent='The artwork could not load. Reload the page to try again.';say('Artwork unavailable. Reload to prepare a fresh proof.',false)};
art.src='data:image/webp;base64,';
compare();
</script>
</body></html>
